import { describe, it, expect } from 'vitest';
describe('T4 baseline', () => {
  it('TransferScreen exports no color-related properties', async () => {
    const mod = await import('./src/screens/TransferScreen.js');
    const colorKeys = Object.keys(mod).filter(k => /color|style|theme|button/i.test(k));
    expect(colorKeys).toEqual([]);
  });
  it('config.ts exports no color or style', async () => {
    const mod = await import('./src/config.js');
    const colorKeys = Object.keys(mod).filter(k => /color|style|theme/i.test(k));
    expect(colorKeys).toEqual([]);
  });
});
